# Archive Change Watcher demo: snapshot diff -> classified change events.
def diff(old,new):
    events=[]
    for k in sorted(set(old)|set(new)):
        if k not in old: events.append(("added",k,None,new[k]))
        elif k not in new: events.append(("deleted",k,old[k],None))
        elif old[k]!=new[k]: events.append(("modified",k,old[k],new[k]))
    return events
old={"a":"v1","b":"v1","c":"v1"}; new={"a":"v1","b":"v2","d":"v1"}
for ev in diff(old,new): print(ev)

